def gen(rng):
    def fmt(N, M, ops):
        lines = [f'{N} {M} {len(ops)}']
        for o in ops:
            lines.append('c' if o is None else f'd {o[0]} {o[1]}')
        return '\n'.join(lines)
    tests = [
        fmt(3, 3, [(1, 1), (3, 3), None, (2, 2), None, (1, 2), None, (2, 3), None]),
        fmt(2, 2, [(1, 1), (1, 1), None, (2, 2), None]),
        fmt(1, 1, [None, (1, 1), None, (1, 1), None]),
        fmt(1, 5, [(1, 1), (1, 3), (1, 5), None, (1, 2), None, (1, 4), None]),
        fmt(5, 1, [(5, 1), (4, 1), (2, 1), None, (3, 1), None]),
        fmt(2, 2, [(1, 1), (2, 2), None, (1, 2), None]),
        fmt(3, 3, [(1, 2), (2, 1), (2, 3), (3, 2), None, (2, 2), None]),
    ]
    for _ in range(40):
        N, M = rng.randint(1, 4), rng.randint(1, 4)
        ops = []
        for _ in range(rng.randint(3, 22)):
            if rng.random() < 0.3:
                ops.append(None)
            else:
                ops.append((rng.randint(1, N), rng.randint(1, M)))
        if None not in ops:
            ops.append(None)
        tests.append(fmt(N, M, ops))
    def big(N, M, Q, pc, local=False):
        ops = []
        for _ in range(Q):
            if rng.random() < pc:
                ops.append(None)
            else:
                ops.append((rng.randint(1, N), rng.randint(1, M)))
        ops[-1] = None
        return fmt(N, M, ops)
    tests.append(big(400, 500, 50000, 0.2))
